//! Fork: "Claude Code" summary provider.
//!
//! Summaries are generated by the user's own Claude Code CLI in print mode (`claude -p`), so they
//! use the Claude account the CLI is logged in with instead of an API key. The CLI can run natively
//! or, on Windows, inside a WSL distribution; only the launcher differs, the CLI call is the same.
//!
//! - `config`: persisted settings (environment, optional executable path).
//! - `detect`: finds a `claude` executable for an environment.
//! - `cli`: builds and runs CLI commands, parses their output.
//! - `commands`: Tauri commands for the settings card.

pub mod commands;

mod cli;
mod config;
mod detect;

use serde::{Deserialize, Serialize};
use std::sync::LazyLock;
use tauri::{AppHandle, Manager, Runtime as TauriRuntime};
use tokio::sync::Mutex;
use tokio_util::sync::CancellationToken;

/// Provider id stored in `settings.provider`.
pub const PROVIDER_ID: &str = "claude-code";

/// Model aliases accepted by `claude --model`; each resolves to the latest model of its family.
pub const MODELS: [&str; 3] = ["sonnet", "opus", "haiku"];

/// Where the user wants Claude Code to run.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
pub enum Environment {
    /// Native install first, then the first WSL distribution that has one.
    #[default]
    Auto,
    Native,
    Wsl { distro: String },
}

#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ClaudeCodeConfig {
    #[serde(default)]
    pub environment: Environment,
    /// Absolute path of `claude` inside the chosen environment. Detected when empty.
    #[serde(default)]
    pub executable: Option<String>,
}

/// Where a concrete `claude` executable runs.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
pub enum Runtime {
    Native,
    Wsl { distro: String },
}

/// A `claude` executable that was found and can be launched.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Installation {
    pub runtime: Runtime,
    pub executable: String,
}

impl Installation {
    /// Human-readable place, used in messages ("this computer", "WSL (Ubuntu)").
    pub fn place(&self) -> String {
        match &self.runtime {
            Runtime::Native => "this computer".to_string(),
            Runtime::Wsl { distro } => format!("WSL ({})", distro),
        }
    }
}

struct State {
    config: ClaudeCodeConfig,
    /// Detection result for `config`, reused until the config changes or the executable vanishes.
    installation: Option<Installation>,
}

static STATE: LazyLock<Mutex<State>> = LazyLock::new(|| {
    Mutex::new(State {
        config: ClaudeCodeConfig::default(),
        installation: None,
    })
});

/// Loads the saved configuration. Call after the database is ready.
pub async fn init<R: TauriRuntime>(app: &AppHandle<R>) {
    let Some(state) = app.try_state::<crate::state::AppState>() else {
        return;
    };
    match config::load(state.db_manager.pool()).await {
        Ok(saved) => STATE.lock().await.config = saved,
        Err(error) => log::warn!("Claude Code settings unavailable, using defaults: {}", error),
    }
}

async fn current_config() -> ClaudeCodeConfig {
    STATE.lock().await.config.clone()
}

async fn set_config(config: ClaudeCodeConfig) {
    let mut state = STATE.lock().await;
    state.config = config;
    state.installation = None;
}

/// The installation for the saved configuration, detected once and then cached.
async fn installation() -> Result<Installation, String> {
    let mut state = STATE.lock().await;
    if let Some(found) = &state.installation {
        return Ok(found.clone());
    }
    let found = detect::resolve(&state.config).await?;
    log::info!("Claude Code found in {}", found.place());
    state.installation = Some(found.clone());
    Ok(found)
}

async fn forget_installation() {
    STATE.lock().await.installation = None;
}

/// Generates one completion with the saved configuration. Used by the summary pipeline.
pub async fn generate(
    model: &str,
    system_prompt: &str,
    user_prompt: &str,
    cancellation_token: Option<&CancellationToken>,
) -> Result<String, String> {
    if !MODELS.contains(&model) {
        return Err(format!("Unknown Claude Code model \"{}\". Choose one in Model Settings.", model));
    }
    let installation = installation().await?;
    let result = cli::complete(&installation, model, system_prompt, user_prompt, cancellation_token).await;
    if matches!(result, Err(cli::Error::NotFound)) {
        // Uninstalled or moved since detection: detect again on the next call.
        forget_installation().await;
    }
    result.map_err(|error| error.user_message(&installation))
}

// Post-meeting features (`crate::post_meeting`, `crate::notion_agent`, `crate::health`) run
// Claude Code through the same installation and the same launcher as the summaries.

pub use cli::{Request, Tools};

/// One print-mode run with the saved configuration.
pub async fn run(request: &Request<'_>, cancellation_token: Option<&CancellationToken>) -> Result<String, String> {
    if !is_model_id(request.model) {
        return Err(format!("Invalid Claude model \"{}\"", request.model));
    }
    let installation = installation().await?;
    let result = cli::print(&installation, request, cancellation_token).await;
    if matches!(result, Err(cli::Error::NotFound)) {
        forget_installation().await;
    }
    result.map_err(|error| error.user_message(&installation))
}

/// Where Claude Code runs ("this computer", "WSL (Ubuntu)") and the output of `claude mcp list`,
/// which reports the state of the account's connectors without using the model.
pub async fn connectors(env: &[(String, String)]) -> Result<(String, String), String> {
    let installation = installation().await?;
    let listing = cli::mcp_list(&installation, env).await.map_err(|error| error.user_message(&installation))?;
    if cli::is_auth_error(&listing) {
        return Err(cli::Error::Claude(listing).user_message(&installation));
    }
    Ok((installation.place(), listing))
}

/// A CLI model alias (`haiku`, `sonnet`, `opus`) or a full model id such as `claude-opus-5-5`.
/// It becomes a command-line argument, so only plain characters are accepted.
pub fn is_model_id(model: &str) -> bool {
    !model.is_empty()
        && model.len() <= 80
        && !model.starts_with('-')
        && model.chars().all(|c| c.is_ascii_alphanumeric() || "-._[]".contains(c))
}

/// End-to-end through `generate` with automatic detection; sends one tiny prompt when logged in:
/// `cargo test -p meetily --lib claude_code::live -- --ignored --nocapture`.
#[cfg(test)]
mod tests {
    #[test]
    fn accepts_only_model_ids() {
        assert!(super::is_model_id("sonnet"));
        assert!(super::is_model_id("claude-opus-5-5"));
        assert!(super::is_model_id("opus[1m]"));
        assert!(!super::is_model_id("--dangerously-skip-permissions"));
        assert!(!super::is_model_id("opus; rm -rf"));
        assert!(!super::is_model_id(""));
    }
}

#[cfg(test)]
mod live {
    #[tokio::test]
    #[ignore]
    async fn generates_a_summary_or_explains_why_not() {
        let result = super::generate(
            "haiku",
            "Summarize the meeting transcript in one short sentence.",
            "<transcript>Alice: the release moves to Friday. Bob: I will update the changelog.</transcript>",
            None,
        )
        .await;
        println!("{:?}", result);
        match result {
            Ok(summary) => assert!(!summary.trim().is_empty()),
            Err(message) => assert!(message.contains("not logged in"), "unexpected error: {}", message),
        }
    }
}
